-- Report ID : RPT_087
-- Report    : Floating Point Setup
-- Module    : Replenishment
-- Source    : Oracle RMS / MFCS RDS Views
-- Generated : Extracted from DVA file
--------------------------------------------------------------------------------

SELECT     TRUNC(SYSDATE)                                       AS report_date,      im.DEPT                                              AS dept_no,     d.DEPT_NAME                                          AS dept_name,     im.CLASS                                             AS class_no,     c.CLASS_NAME                                         AS class_name,     im.SUBCLASS                                          AS subclass_no,     sc.SUB_NAME                                          AS subclass_name,      im.ITEM                                              AS item_id,     im.ITEM_DESC                                         AS item_description,     im.STANDARD_UOM                                      AS uom,     im.PACK_IND                                          AS pack_ind,     im.STATUS                                            AS item_status,      ril.LOCATION                                         AS location_id,     il.LOC_TYPE                                          AS loc_type,     CASE il.LOC_TYPE         WHEN 'S' THEN 'Store'         WHEN 'W' THEN 'Warehouse'     END                                                  AS loc_type_desc,     CASE il.LOC_TYPE         WHEN 'S' THEN st.STORE_NAME         WHEN 'W' THEN wh.WH_NAME     END                                                  AS location_name,     il.STATUS                                            AS item_loc_status,     CASE il.STATUS         WHEN 'A' THEN 'Active'         WHEN 'C' THEN 'Discontinued'         WHEN 'I' THEN 'Inactive'         WHEN 'D' THEN 'Delete'     END                                                  AS item_loc_status_desc,      ril.REPL_METHOD                                      AS repl_method,     'Floating Point'                                     AS repl_method_desc,     ril.STOCK_CAT                                        AS stock_category,     CASE ril.STOCK_CAT         WHEN 'C' THEN 'Cross-Docked'         WHEN 'D' THEN 'Direct to Store'         WHEN 'L' THEN 'WH/Cross Link'         WHEN 'W' THEN 'Warehouse Stocked'         ELSE ril.STOCK_CAT     END                                                  AS stock_category_desc,      ril.REPL_ORDER_CTRL                                  AS order_control,     CASE ril.REPL_ORDER_CTRL         WHEN 'A' THEN 'Automatic'         WHEN 'B' THEN 'Buyer Worksheet'         WHEN 'M' THEN 'Manual'         WHEN 'S' THEN 'Semi-Automatic'     END                                                  AS order_control_desc,      ril.MIN_STOCK                                        AS min_stock,     ril.MAX_STOCK                                        AS max_stock,     NVL(ril.MAX_STOCK, 0) - NVL(ril.MIN_STOCK, 0)      AS repl_band,      mra.PRES_STOCK                                       AS presentation_stock,     ril.DEMO_STOCK                                       AS demo_stock,      ils.STOCK_ON_HAND                                    AS current_soh,     CASE         WHEN ils.STOCK_ON_HAND < NVL(ril.MIN_STOCK, 0)         THEN 'BELOW MIN - REORDER DUE'         WHEN ils.STOCK_ON_HAND BETWEEN              NVL(ril.MIN_STOCK, 0) AND NVL(ril.MAX_STOCK, 0)         THEN 'WITHIN RANGE'         WHEN ils.STOCK_ON_HAND > NVL(ril.MAX_STOCK, 0)         THEN 'ABOVE MAX - OVERSTOCK'         ELSE 'UNKNOWN'     END                                                  AS stock_position,     GREATEST(NVL(ril.MAX_STOCK, 0) - NVL(ils.STOCK_ON_HAND, 0), 0)                                                          AS implied_roq,      ril.PRIMARY_REPL_SUPPLIER                            AS repl_supplier_id,     sp.SUP_NAME                                          AS supplier_name,     isc.LEAD_TIME                                        AS supplier_lead_time,     isc.PICKUP_LEAD_TIME                                 AS pickup_lead_time,      iscl.PICKUP_LEAD_TIME                                AS loc_pickup_lt_override,      ril.SUPP_LEAD_TIME                                   AS effective_lead_time,     ril.PICKUP_LEAD_TIME                                 AS effective_pickup_lt,     ril.ADJ_SUPP_LEAD_TIME                               AS adj_supp_lead_time,     ril.ADJ_PICKUP_LEAD_TIME                             AS adj_pickup_lead_time,     ril.WH_LEAD_TIME                                     AS wh_lead_time,     ril.SOURCE_WH                                        AS source_warehouse,      ril.REVIEW_CYCLE                                     AS review_cycle,     CASE ril.REVIEW_CYCLE         WHEN '0' THEN 'Every Week'         WHEN '1' THEN 'Every Day'         WHEN '2' THEN 'Every 2 Weeks'         WHEN '3' THEN 'Every 3 Weeks'         WHEN '4' THEN 'Every 4 Weeks'         WHEN '5' THEN 'Every 5 Weeks'         WHEN '6' THEN 'Every 6 Weeks'         WHEN '7' THEN 'Every 7 Weeks'         WHEN '8' THEN 'Every 8 Weeks'         ELSE 'Every ' || ril.REVIEW_CYCLE || ' Weeks'     END                                                  AS review_cycle_desc,      mra.MONDAY_IND                                       AS mon,     mra.TUESDAY_IND                                      AS tue,     mra.WEDNESDAY_IND                                    AS wed,     mra.THURSDAY_IND                                     AS thu,     mra.FRIDAY_IND                                       AS fri,     mra.SATURDAY_IND                                     AS sat,     mra.SUNDAY_IND                                       AS sun,      mra.NON_SCALING_IND                                  AS scaling_exempt_ind,     mra.MAX_SCALE_VALUE                                  AS max_scale_amount,      mra.MIN_STOCK                                        AS master_min_stock,     mra.MAX_STOCK                                        AS master_max_stock,     mra.PRES_STOCK                                       AS master_pres_stock,      CASE WHEN ril.MAX_STOCK IS NULL OR ril.MAX_STOCK = 0          THEN 'WARN: MAX STOCK NOT SET' ELSE 'OK'     END                                                  AS max_stock_flag,     CASE WHEN ril.MIN_STOCK IS NULL OR ril.MIN_STOCK = 0          THEN 'WARN: MIN STOCK NOT SET' ELSE 'OK'     END                                                  AS min_stock_flag,     CASE WHEN ril.PRIMARY_REPL_SUPPLIER IS NULL               AND ril.STOCK_CAT IN ('C','D','L','W')          THEN 'WARN: SUPPLIER MISSING' ELSE 'OK'     END                                                  AS supplier_flag,     CASE WHEN NVL(isc.PICKUP_LEAD_TIME, 0) = 0               AND ril.STOCK_CAT IN ('C','D','L','W')          THEN 'WARN: PICKUP LEAD TIME MISSING' ELSE 'OK'     END                                                  AS pickup_lt_flag,      CASE         WHEN (ril.MAX_STOCK IS NULL OR ril.MAX_STOCK = 0)           OR (ril.PRIMARY_REPL_SUPPLIER IS NULL               AND ril.STOCK_CAT IN ('C','D','L','W'))           OR (NVL(isc.PICKUP_LEAD_TIME, 0) = 0               AND ril.STOCK_CAT IN ('C','D','L','W'))         THEN 'INCOMPLETE SETUP'         WHEN (ril.MIN_STOCK IS NULL OR ril.MIN_STOCK = 0)         THEN 'REVIEW RECOMMENDED'         ELSE 'FULLY CONFIGURED'     END                                                  AS setup_status,      ils.UNIT_COST                                        AS unit_cost,     ils.AV_COST                                          AS weighted_avg_cost,     il.SELLING_UNIT_RETAIL                               AS unit_retail,      ril.LAST_UPDATE_DATETIME                             AS last_repl_update,     TRUNC(SYSDATE) - TRUNC(ril.LAST_UPDATE_DATETIME)    AS days_since_update  FROM     MFCS_RDS.RDS_WV_REPL_ITEM_LOC              ril      JOIN  MFCS_RDS.RDS_WV_ITEM_LOC             il    ON  ril.ITEM          = il.ITEM                                                      AND  ril.LOCATION      = il.LOC     JOIN  MFCS_RDS.RDS_WV_ITEM_MASTER          im    ON  ril.ITEM          = im.ITEM                                                      AND  im.TRAN_LEVEL     = im.ITEM_LEVEL     JOIN  MFCS_RDS.RDS_WV_DEPS                 d     ON  im.DEPT           = d.DEPT     JOIN  MFCS_RDS.RDS_WV_CLASS                c     ON  im.DEPT           = c.DEPT                                                      AND  im.CLASS          = c.CLASS     JOIN  MFCS_RDS.RDS_WV_SUBCLASS             sc    ON  im.DEPT           = sc.DEPT                                                      AND  im.CLASS          = sc.CLASS                                                      AND  im.SUBCLASS       = sc.SUBCLASS      LEFT JOIN MFCS_RDS.RDS_WV_STORE            st    ON  ril.LOCATION      = st.STORE                                                      AND  il.LOC_TYPE       = 'S'     LEFT JOIN MFCS_RDS.RDS_WV_WH              wh     ON  ril.LOCATION      = wh.WH                                                      AND  il.LOC_TYPE       = 'W'      LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC_SOH    ils    ON  ril.ITEM          = ils.ITEM                                                      AND  ril.LOCATION      = ils.LOC                                                      AND  ils.LOC_TYPE      = il.LOC_TYPE      LEFT JOIN MFCS_RDS.RDS_WV_ITEM_SUPP_COUNTRY isc  ON  ril.ITEM          = isc.ITEM                                                      AND  ril.PRIMARY_REPL_SUPPLIER = isc.SUPPLIER                                                      AND  isc.PRIMARY_SUPP_IND      = 'Y'                                                      AND  isc.PRIMARY_COUNTRY_IND   = 'Y'      LEFT JOIN MFCS_RDS.RDS_WV_ITEM_SUPP_COUNTRY_LOC iscl                                                       ON  ril.ITEM          = iscl.ITEM                                                      AND  ril.PRIMARY_REPL_SUPPLIER = iscl.SUPPLIER                                                      AND  iscl.LOC          = ril.LOCATION      LEFT JOIN MFCS_RDS.RDS_WV_SUPS             sp    ON  ril.PRIMARY_REPL_SUPPLIER = sp.SUPPLIER      LEFT JOIN MFCS_RDS.RDS_WV_MASTER_REPL_ATTR mra   ON  ril.ITEM          = mra.ITEM                                                      AND  ril.LOCATION      = mra.LOCATION  WHERE     ril.REPL_METHOD     = 'F'     AND il.STATUS       IN ('A', 'C')     AND im.STATUS        = 'A'  ORDER BY     CASE         WHEN (ril.MAX_STOCK IS NULL OR ril.MAX_STOCK = 0)           OR (ril.PRIMARY_REPL_SUPPLIER IS NULL AND ril.STOCK_CAT IN ('C','D','L','W'))           OR (NVL(isc.PICKUP_LEAD_TIME,0) = 0  AND ril.STOCK_CAT IN ('C','D','L','W'))         THEN 'INCOMPLETE SETUP'         WHEN (ril.MIN_STOCK IS NULL OR ril.MIN_STOCK = 0)         THEN 'REVIEW RECOMMENDED'         ELSE 'FULLY CONFIGURED'     END,     d.DEPT_NAME,     c.CLASS_NAME,     sc.SUB_NAME,     im.ITEM_DESC,     CASE il.LOC_TYPE WHEN 'S' THEN st.STORE_NAME WHEN 'W' THEN wh.WH_NAME END